import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

final class InvoicePager {
    private final int pageSize;

    InvoicePager(int pageSize) {
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be positive");
        }
        this.pageSize = pageSize;
    }

    // Returns a copy of the zero-based page of invoice ids. The last page may hold fewer
    // than pageSize ids, and any page past the end is empty.
    List<String> page(List<String> invoiceIds, int pageIndex) {
        Objects.requireNonNull(invoiceIds, "invoiceIds");
        if (pageIndex < 0) {
            throw new IllegalArgumentException("pageIndex must not be negative");
        }
        long from = (long) pageIndex * pageSize;
        if (from >= invoiceIds.size()) {
            return new ArrayList<>();
        }
        int start = (int) from;
        return new ArrayList<>(invoiceIds.subList(start, start + pageSize));
    }
}

