final class InvoicePager {
    private final int pageSize;

    InvoicePager(int pageSize) {
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be positive");
        }
        this.pageSize = pageSize;
    }

    // Returns a copy of the zero-based page of invoice ids. The last page may hold fewer
    // than pageSize ids, and any page past the end is empty.
    List<String> page(List<String> invoiceIds, int pageIndex) {
        Objects.requireNonNull(invoiceIds, "invoiceIds");
        if (pageIndex < 0) {
            throw new IllegalArgumentException("pageIndex must not be negative");
        }
        long from = (long) pageIndex * pageSize;
        if (from >= invoiceIds.size()) {
            return new ArrayList<>();
        }
        int start = (int) from;
        int end = start + Math.min(pageSize, invoiceIds.size() - start);
        return new ArrayList<>(invoiceIds.subList(start, end));
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

final class DocumentVersions {
    private final Map<String, Integer> versions = new HashMap<>();

    synchronized void create(String docId) {
        Objects.requireNonNull(docId, "docId");
        versions.putIfAbsent(docId, 1);
    }

    // Returns the latest version of the document, or null if the document is unknown.
    synchronized Integer current(String docId) {
        return versions.get(docId);
    }

    // Optimistic locking: an edit is accepted only if the client saw the latest version.
    // expectedVersion comes from the request body and is null when the client omitted it.
    synchronized boolean tryAdvance(String docId, Integer expectedVersion) {
        Integer current = versions.get(docId);
        if (current == null || expectedVersion == null) {
            return false;
        }
        if (current != expectedVersion) {
            return false;
        }
        versions.put(docId, current + 1);
        return true;
    }
}

