import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Optional;
import javax.sql.DataSource;

final class CustomerRepository {
    private final DataSource dataSource;

    CustomerRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    // Called on every request; connections come from a bounded pool.
    Optional<String> findEmail(long customerId) throws SQLException {
        Connection connection = dataSource.getConnection();
        try (PreparedStatement statement = connection.prepareStatement(
                "SELECT email FROM customers WHERE id = ?")) {
            statement.setLong(1, customerId);
            try (ResultSet rs = statement.executeQuery()) {
                return rs.next() ? Optional.ofNullable(rs.getString("email")) : Optional.empty();
            }
        }
    }
}

