import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

final class LoginAttemptTracker {
    private static final int MAX_FAILURES = 5;
    private final ConcurrentMap<String, Integer> failures = new ConcurrentHashMap<>();

    // Invoked concurrently by request threads; every failed login must be counted.
    void recordFailure(String username) {
        int count = failures.getOrDefault(username, 0);
        failures.put(username, count + 1);
    }

    boolean isLocked(String username) {
        return failures.getOrDefault(username, 0) >= MAX_FAILURES;
    }

    void recordSuccess(String username) {
        failures.remove(username);
    }
}

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

final class LoginAttemptTracker {
    private static final int MAX_FAILURES = 5;
    private final ConcurrentMap<String, Integer> failures = new ConcurrentHashMap<>();

    // Invoked concurrently by request threads; every failed login must be counted.
    void recordFailure(String username) {
        failures.merge(username, 1, Integer::sum);
    }

    boolean isLocked(String username) {
        return failures.getOrDefault(username, 0) >= MAX_FAILURES;
    }

    void recordSuccess(String username) {
        failures.remove(username);
    }
}

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;

final class RefundPolicy {
    private RefundPolicy() {
    }

    // Only orders that were actually charged get a refund; zero-total (free) orders are skipped.
    // Charged amounts are loaded from a NUMERIC(12,2) column, so they always carry two decimal places.
    static boolean requiresRefund(BigDecimal chargedAmount) {
        return chargedAmount != null && !chargedAmount.equals(BigDecimal.ZERO);
    }

    static List<CancelledOrder> refundable(List<CancelledOrder> cancelled) {
        Objects.requireNonNull(cancelled, "cancelled");
        return cancelled.stream()
                .filter(order -> requiresRefund(order.charged()))
                .toList();
    }
}

record CancelledOrder(String id, BigDecimal charged) {}

