final class GatewayConfigLoader {
    private GatewayConfigLoader() {
    }

    // Startup must abort if the payment gateway configuration cannot be read; running
    // with missing settings would send payments to the wrong endpoint.
    static Properties load(Path file) {
        Properties props = new Properties();
        try (InputStream in = Files.newInputStream(file)) {
            props.load(in);
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot read gateway config " + file, e);
        }
        return props;
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;

final class ReportDownloads {
    private final Path reportsRoot;

    ReportDownloads(Path reportsRoot) {
        this.reportsRoot = reportsRoot.toAbsolutePath().normalize();
    }

    // fileName comes straight from the download URL; only files under reportsRoot may be served.
    byte[] read(String fileName) throws IOException {
        Path file = reportsRoot.resolve(fileName);
        if (!Files.isRegularFile(file)) {
            throw new NoSuchFileException(fileName);
        }
        return Files.readAllBytes(file);
    }
}

import java.io.IOException;
import java.nio.file.LinkOption;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;

final class ReportDownloads {
    private final Path reportsRoot;

    ReportDownloads(Path reportsRoot) {
        this.reportsRoot = reportsRoot.toAbsolutePath().normalize();
    }

    // fileName comes straight from the download URL; only files under reportsRoot may be served.
    byte[] read(String fileName) throws IOException {
        Path file = reportsRoot.resolve(fileName).normalize();
        if (!file.startsWith(reportsRoot) || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
            throw new NoSuchFileException(fileName);
        }
        return Files.readAllBytes(file);
    }
}

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.util.Objects;

final class StatementNaming {
    // Statement files are named after the calendar date they cover, e.g. statement-2026-12-31.pdf,
    // and archived in a folder for that calendar month, e.g. 2026-12/statement-2026-12-31.pdf.
    private static final DateTimeFormatter FILE_DATE = DateTimeFormatter.ofPattern("YYYY-MM-dd");
    private static final DateTimeFormatter FOLDER_MONTH = DateTimeFormatter.ofPattern("uuuu-MM");

    private StatementNaming() {
    }

    static String fileName(LocalDate statementDate) {
        Objects.requireNonNull(statementDate, "statementDate");
        return "statement-" + FILE_DATE.format(statementDate) + ".pdf";
    }

    static String archivePath(LocalDate statementDate) {
        Objects.requireNonNull(statementDate, "statementDate");
        return FOLDER_MONTH.format(YearMonth.from(statementDate)) + "/" + fileName(statementDate);
    }
}

